import numpy as np
from typing import Union


class NumericLimits(object):
    """Class providing interface to extract numerical limits for given data type."""

    @staticmethod
    def _get_number_limits_class(dtype):
        # type: (np.dtype) -> Union[IntegralLimits, FloatingPointLimits]
        """Return specialized class instance with limits set for given data type."""
        if np.issubdtype(dtype, np.integer):
            return IntegralLimits(dtype)
        elif np.issubdtype(dtype, np.floating):
            return FloatingPointLimits(dtype)
        else:
            raise ValueError("Unsupported data type")

class IntegralLimits(object):
    """Class providing methods to extract numerical limits for integral data types."""

    def __init__(self, dtype):
        self.dtype = dtype

    def get_min_value(self):
        return np.iinfo(self.dtype).min

    def get_max_value(self):
        return np.iinfo(self.dtype).max


class FloatingPointLimits(object):
    """Class providing methods to extract numerical limits for floating-point data types."""

    def __init__(self, dtype):
        self.dtype = dtype

    def get_min_value(self):
        return np.finfo(self.dtype).min

    def get_max_value(self):
        return np.finfo(self.dtype).max

    def get_epsilon(self):
        return np.finfo(self.dtype).eps

    def get_precision(self):
        return np.finfo(self.dtype).precision


# Usage example
int_limits = NumericLimits._get_number_limits_class(np.int32)
print(int_limits.get_min_value())  # Output: -2147483648
