import numpy as np

def reject_outliers(arr, reject_fullname, zero_section=None, scale_section=None, scale_to_0th=None):
    if reject_fullname == 'sigclip':
        if zero_section is not None:
            arr[zero_section[0]:zero_section[1]] = 0  # Zero sectioning
        if scale_section is not None:
            section = arr[scale_section[0]:scale_section[1]]
            if scale_to_0th:
                section -= np.percentile(section, 0)  # Scale to 0th percentile
            else:
                section -= np.mean(section)  # Scale to mean
            arr[scale_section[0]:scale_section[1]] = section
        # Perform rejection using "sigclip" method
        while True:
            mean = np.mean(arr)
            std_dev = np.std(arr)
            mask = np.abs(arr - mean) < 3 * std_dev  # Define mask for values within 3 standard deviations
            if mask.all():  # If all values are within 3 standard deviations, break the loop
                break
            arr = arr[mask]  # Update array with non-outlier values
        return arr
    else:
        raise ValueError("Invalid rejection method. Only 'sigclip' method is supported.")
```

The `reject_outliers` function first checks if the specified rejection method is 'sigclip'. If so, it applies the optional zero sectioning and scaling to the input array. Then, it iteratively applies the "sigclip" rejection method by removing values that are more than 3 standard deviations away from the mean. Finally, the function returns the array with outliers rejected. If an invalid rejection method is provided, the function raises a ValueError.

