        self.num_players = num_players
        self.num_rounds = num_rounds
        self.results = []

    def roll_dice(self):
        return np.random.randint(1, 7)  # Generate a random dice value using numpy

    def play_round(self, player_id, round_num):
        dice_value = self.roll_dice()
        self.results.append((player_id, round_num, dice_value))

    def simulate_game(self):
        threads = []
        for round_num in range(1, self.num_rounds + 1):
            for player_id in range(1, self.num_players + 1):
                thread = threading.Thread(target=self.play_round, args=(player_id, round_num))
                threads.append(thread)
                thread.start()

        for thread in threads:
            thread.join()

    def save_results(self):
        with open("dice_results.txt", "w") as file:
            for result in self.results:
                file.write(f"Player {result[0]}, Round {result[1]}, Dice Value: {result[2]}\n")

if __name__ == "__main__":
