import numpy as np

def compute_edge_embeddings(X, ebunch, method='hadamard'):
    edge_embeddings = []

    for edge in ebunch:
        u, v = edge
        if method == 'hadamard':
            emb = np.multiply(X[u], X[v])
        elif method == 'average':
            emb = (X[u] + X[v]) / 2
        elif method == 'weighted_l1':
            emb = np.abs(X[u] - X[v])
            emb = emb / np.sum(emb)  # Normalize to obtain weights
            emb = np.multiply(X[u], emb) + np.multiply(X[v], 1 - emb)
        else:
            raise ValueError("Invalid method specified")

        edge_embeddings.append(emb)

    return np.array(edge_embeddings)
