max_points = 2000

# Define waveforms
def square_wave(x, terms):
    wave = 0
    for n in range(1, terms * 2, 2):
        wave += (4 / (n * np.pi)) * np.sin(n * x)
    return wave

def sawtooth_wave(x, terms):
    wave = 0
    for n in range(1, terms + 1):
        wave += (1 / n) * np.sin(n * x)
    return wave

def triangle_wave(x, terms):
    wave = 0
    for n in range(1, terms * 2, 2):
        wave += ((8 / (np.pi ** 2)) * ((-1) ** ((n - 1) / 2)) / (n ** 2)) * np.sin(n * x)
    return wave

# Initialize Pygame
pg.init()
screen = pg.display.set_mode((width, height))
clock = pg.time.Clock()

# Main loop
running = True
wave_choice = 1  # default to square
while running:
