        if event.type == pg.QUIT:
            running = False
        elif event.type == pg.KEYDOWN:
            if event.key == pg.K_1:
                wave_choice = 1  # Square wave
            elif event.key == pg.K_2:
                wave_choice = 2  # Sawtooth wave
            elif event.key == pg.K_3:
                wave_choice = 3  # Triangle wave
            elif event.key == pg.K_UP:
                terms += 1
            elif event.key == pg.K_DOWN:
                terms = max(1, terms - 1)
            elif event.key == pg.K_RIGHT:
                time_step += 0.001
            elif event.key == pg.K_LEFT:
                time_step = max(0.001, time_step - 0.001)

    screen.fill((255, 255, 255))

    x_values = np.linspace(0, 2 * np.pi, max_points)
    if wave_choice == 1:
        y_values = square_wave(x_values, terms)
    elif wave_choice == 2:
        y_values = sawtooth_wave(x_values, terms)
    else:
        y_values = triangle_wave(x_values, terms)

    points = [(x, int(y * height / 2 + height / 2)) for x, y in zip(x_values, y_values)]
    pg.draw.lines(screen, (0, 0, 0), False, points, 2)

    pg.display.flip()
    clock.tick(60)

pg.quit()
