import torch

class CustomDataset(torch.utils.data.Dataset):
    def __init__(self, data, targets):
        self.data = data
        self.targets = targets
        # Define the mask based on certain conditions
        # Example: mask = (self.targets > 0)
        # If the condition is not specified, set the mask to all True
        # Example: mask = torch.ones_like(self.targets).bool()

    def __len__(self):
        return self.data.size(0)

    def __getitem__(self, index):
        # Complete the __getitem__ method to return the input data and target label for the given index, considering the filtering logic based on the mask tensor
        mask = torch.ones_like(self.targets).bool()  # Example: mask = (self.targets > 0)
        task_ids = torch.masked_select(torch.arange(self.targets.size(0)), mask)
        if index < len(task_ids):
            selected_index = task_ids[index]
            return self.data[selected_index], self.targets[selected_index]
        else:
            raise IndexError("Index out of range")
