import numpy as np

def reshape_image(input_data, image_data):
    layout = input_data["inputs"][0]["layout"]
    color_format = input_data["inputs"][0]["color_format"]

    if color_format == "BGR":
        # Convert BGR to RGB
        image_data = image_data[..., ::-1]

    # Rearrange dimensions according to layout
    if layout == ["N", "H", "W", "C"]:
        return image_data.transpose(0, 3, 1, 2)
    elif layout == ["N", "C", "H", "W"]:
        return image_data.transpose(0, 3, 1, 2)
    elif layout == ["N", "C", "W", "H"]:
        return image_data.transpose(0, 3, 2, 1)
    else:
        raise ValueError("Unsupported layout")

# Example usage
